public class PiePlot_getMaximumExplodePercent_TriageGen2Test {

    private PiePlot piePlot;
    private DefaultPieDataset dataset;

    @Before
    public void setUp() {
        dataset = new DefaultPieDataset();
        piePlot = new PiePlot(dataset);
    }

    @Test
    public void testGetMaximumExplodePercent_EmptyDataset() {
        // Case: Dataset has no keys, result should be 0.0
        assertEquals(0.0, piePlot.getMaximumExplodePercent(), 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_NoExplodeValues() {
        // Case: Dataset has keys but no explode percentages set
        dataset.setValue("A", 10.0);
        dataset.setValue("B", 20.0);

        assertEquals(0.0, piePlot.getMaximumExplodePercent(), 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_SingleValue() {
        // Case: One explode value set
        dataset.setValue("A", 10.0);
        piePlot.setExplodePercent("A", 0.15);

        assertEquals(0.15, piePlot.getMaximumExplodePercent(), 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_MultipleValues() {
        // Case: Multiple explode values, find the max
        dataset.setValue("A", 10.0);
        dataset.setValue("B", 20.0);
        dataset.setValue("C", 30.0);

        piePlot.setExplodePercent("A", 0.1);
        piePlot.setExplodePercent("B", 0.5);
        piePlot.setExplodePercent("C", 0.3);

        assertEquals(0.5, piePlot.getMaximumExplodePercent(), 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_WithNullExplodeValue() {
        // Case: Simulate an entry in the dataset that exists but has a null explode value 
        // (Note: In standard PiePlot, setExplodePercent usually handles this, 
        // but the code logic explicitly checks for null)

        // We use a mock dataset to control the iterator behavior and keys
        PieDataset mockDataset = mock(PieDataset.class);
        Iterator<Comparable> mockIterator = mock(Iterator.class);

        when(mockDataset.getKeys()).thenReturn(mockDataset.getKeys()); // Not strictly needed but for safety
        // Using real dataset for key management but mocking the logic flow via the actual class behavior
        // Since we cannot easily inject a null into the internal Map via public API, 
        // we rely on the fact that the code handles 'explode != null'

        dataset.setValue("A", 10.0);
        dataset.setValue("B", 20.0);
        piePlot.setDataset(dataset);

        piePlot.setExplodePercent("A", 0.2);
        // "B" remains null in the explodePercentages map

        assertEquals(0.2, piePlot.getMaximumExplodePercent(), 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_ZeroAndNegative() {
        // Case: Values are 0 or effectively nothing
        dataset.setValue("A", 10.0);
        piePlot.setExplodePercent("A", 0.0);

        assertEquals(0.0, piePlot.getMaximumExplodePercent(), 0.001);
    }
}
